def BellmanFord(edges,num_vertex,start):
    inf=float("inf")
    dist=[inf for i in range(num_vertex)]
    dist[start]=0
    for i in range(num_vertex):
        for edge in edges:
            if dist[edge[0]]!=inf and dist[edge[1]]>dist[edge[0]]+edge[2]:
                dist[edge[1]]=dist[edge[0]]+edge[2]
                if i==num_vertex-1 and edge[1]==num_vertex-1:
                    return -1
    return dist

