from collections import defaultdict


MOD = 10 ** 9 + 7

# nを素因数分解する(O(n ^ (1 / 2)))
# primeFactorDecomposition(12): {2: 2, 3: 1}
def prime_factor_decomposition(n):
    m = defaultdict(int)
    while n > 1:
        find_factor = False

        for i in range(2, int(n ** 1/2) + 1):
            if n % i == 0:
                m[i] += 1
                n //= i
                find_factor = True
                break

        if not find_factor:
            m[n] += 1
            break
    return m


def main():
    N = int(input())
    all_m = defaultdict(int)
    for i in range(1, N + 1):
        m = prime_factor_decomposition(i)

        for k, v in m.items():
            all_m[k] += v

    ans = 1
    for v in all_m.values():
        ans *= (v + 1)
        ans %= MOD

    print(ans)


