def solve(N, M, a, b, c):
    d = [-float('inf') for _ in range(N)]
    d[0] = 0

    for n in range(M):
        for aa, bb, cc in zip(a, b, c):
            if d[bb-1] < d[aa-1] + cc:
                d[bb-1] = d[aa-1] + cc
    dp = d[N-1]
    for n in range(M):
        for aa, bb, cc in zip(a, b, c):
            if d[bb-1] < d[aa-1] + cc:
                d[bb-1] = d[aa-1] + cc

    if d[N-1] > dp:
        return 'inf'
    else:
        return d[N-1]


