import collections


def prepare():
    N = int(input())
    A = list(map(int, input().split(" ")))
    return N, A


def combinations(N, A):
    grouped_A = dict(collections.Counter(A))
    if N % 2 == 1:
        for i, c in enumerate(sorted(grouped_A.items(), key=lambda x: x[0])):
            if c[0] != 2 * i:
                return 0
            if i == 0 and c[1] != 1:
                return 0
        return 2 ** (len(set(grouped_A.keys())) - 1)
    else:
        for i, c in enumerate(sorted(grouped_A.items(), key=lambda x: x[0]), start=1):
            if c[0] != 2 * i - 1:
                return 0
            if c[1] != 2:
                return 0
        return 2 ** len(set(grouped_A.keys()))


if __name__ == "__main__":
    N, A = prepare()
    ans = combinations(N, A)
    c = 10 ** 9 + 7
    print(ans % c)

