import sys


def IN_I(): return int(sys.stdin.readline().rstrip())
def IN_LI(): return list(map(int, sys.stdin.readline().rstrip().split()))
INF = float('inf')


class UnionFind:
    def __init__(self, n):
        self.par = [i for i in range(n)] # 親
        self.rank = [0 for _ in range(n)] # 根の深さ

    # xの属する木の根を求める
    def find(self, x):
        if self.par[x] == x:
            return x
        else:
            self.par[x] = self.find(self.par[x])
            return self.par[x]

    # xとyの属する集合のマージ
    def unite(self, x, y):
        x = self.find(x)
        y = self.find(y)
        if x == y:
            return
        if self.rank[x] < self.rank[y]:
            self.par[x] = y
        else:
            self.par[y] = x
            if self.rank[x] == self.rank[y]:
                self.rank[x] += 1

    # xとyが同じ集合に属するかを判定
    def same(self, x, y):
        return self.find(x) == self.find(y)


def kruskal(n, edges):
    uf = UnionFind(n)
    cost = 0
    for e in edges:
        w, s, t = e
        if not uf.same(s, t):
            cost += w
            uf.unite(s, t)
    return cost


def main():
    N = IN_I()
    g = []
    for i in range(N):
        x, y = IN_LI()
        g.append((x, y, i))
    x_sort = sorted(g)
    y_sort = sorted(g, key=lambda x:x[1])

    edge = []

    for i in range(1, N):
        dx = abs(x_sort[i][0] - x_sort[i - 1][0])
        dy = abs(x_sort[i][1] - x_sort[i - 1][1])
        edge.append((min(dx, dy), x_sort[i - 1][2], x_sort[i][2]))

    for i in range(1, N):
        dx = abs(y_sort[i][0] - y_sort[i - 1][0])
        dy = abs(y_sort[i][1] - y_sort[i - 1][1])
        edge.append((min(dx, dy), y_sort[i - 1][2], y_sort[i][2]))

    edge.sort()

    print(kruskal(N, edge))


