def dfs(v, visited):
    # visitedに0が含まれている → 全頂点を訪れていない
    if 0 not in visited:
        return 1

    # 有効パスの個数をカウント
    cnt = 0
    for i in range(N):
        if Graph[v][i] == 1:
            if visited[i] == 0:
                visited[i] = 1
                cnt += dfs(i,visited)
                visited[i] = 0
    return cnt

