import math


def factorization(n):
    arr = []
    temp = n
    for i in range(2, int(-(-n**0.5 // 1)) + 1):
        if temp % i == 0:
            cnt = 0
            while temp % i == 0:
                cnt += 1
                temp //= i
            arr.append([i, cnt])

    if temp != 1:
        arr.append([temp, 1])

    if arr == []:
        arr.append([n, 1])

    return arr


def main():
    N = int(input())
    MOD = 10**9 + 7

    A = [0 for _ in range(N + 1)]
    for i in range(2, N + 1):
        x = factorization(i)
        for a, b in x:
            A[a] += b

    ans = 1
    for a in A:
        ans *= (a + 1)
        ans %= MOD

    print(ans)


