def bellmanford(E,N):
    score=[inf for i in range(N)]
    score[0]=0
    for i in range(N-1):
        for edge in E:
            u=edge[0]
            v=edge[1]
            if u!=inf:
                score[v]=min(score[v],score[u]+edge[2])
    temp=score[N-1]
    score = [inf for i in range(N)]
    score[0] = 0
    for i in range(N):
        for edge in E:
            u=edge[0]
            v=edge[1]
            if u!=inf:
                score[v]=min(score[v],score[u]+edge[2])
    loop=(temp!=score[N-1])

    return temp,loop


