import sys

sys.setrecursionlimit(10 ** 6)

def input():
    return sys.stdin.readline().rstrip()

def main():
    # x方向、y方向それぞれ値が小さいものから道をつなげていく
    # すでに繋がっているかはunion-findで確認

    class UnionFind():
        def __init__(self, n):
            self.n = n
            self.parents = [-1] * n

        def find(self, x):
            if self.parents[x] < 0:
                return x
            else:
                self.parents[x] = self.find(self.parents[x])
                return self.parents[x]

        def union(self, x, y):
            x = self.find(x)
            y = self.find(y)

            if x == y:
                return

            if self.parents[x] > self.parents[y]:
                x, y = y, x

            self.parents[x] += self.parents[y]
            self.parents[y] = x

        def size(self, x):
            return -self.parents[self.find(x)]

        def same(self, x, y):
            return self.find(x) == self.find(y)


    n = int(input())
    xy = [[int(v) for v in input().split()] for _ in range(n)]

    x = []
    y = []
    for i in range(n):
        x.append((xy[i][0], i))
        y.append((xy[i][1], i))

    x.sort()
    y.sort()

    dist = []
    for i in range(1, n):
        dist.append((x[i][0] - x[i - 1][0], (x[i][1], x[i - 1][1])))

    for i in range(1, n):
        dist.append((y[i][0] - y[i - 1][0], (y[i][1], y[i - 1][1])))

    dist.sort()
    ans = 0
    uf = UnionFind(n)
    for v in dist:
        x, y = v[1]
        if uf.same(x, y):
            continue
        else:
            ans += v[0]
            uf.union(x, y)

    print(ans)

