class UnionFind:
    def __init__(self, size):
        self.parent = [-1] * size
        self.size = [1] * size

    def get_root(self, id):
        if self.parent[id] != -1:
            return self.get_root(self.parent[id])
        else:
            return id

    def is_same(self, id1, id2):
        root1 = self.get_root(id1)
        root2 = self.get_root(id2)
        return root1 == root2 and self.get_root(id1) != -1

    def unite(self, id1, id2):
        root1 = self.get_root(id1)
        root2 = self.get_root(id2)

        if root1 == root2 and root1 != -1: return None

        # 大きい方に小さい方をぶら下げる
        # サイズはrootの要素だけ管理しておけばいい
        if self.size[root1] > self.size[root2]:
            self.parent[root2] = root1
            self.size[root1] += self.size[root2]
        else:
            self.parent[root1] = root2
            self.size[root2] += self.size[root1]

    def get_group_size(self, id):
        return self.size[self.get_root(id)]


def resolve():
    N = int(input())
    positions = []
    for _ in range(N):
        positions.append([int(v) for v in input().split()])

    x_sorted_index = sorted(range(N), key=lambda i: positions[i][0])
    y_sorted_index = sorted(range(N), key=lambda i: positions[i][1])

    edges = []
    #### Kruskal
    uf = UnionFind(N)

    def add_edge_x(left, right):
        edges.append([left, right,
                      abs(positions[left][0] - positions[right][0])])

    def add_edge_y(left, right):
        edges.append([left, right,
                      abs(positions[left][1] - positions[right][1])])

    current_val = None
    previous_index = None
    current_index = None
    for index in x_sorted_index:
        if positions[index][0] == current_val:
            # 前と同じ
            uf.unite(index, current_index)
        else:
            # 前と違う
            previous_index = current_index
            current_val = positions[index][0]
            current_index = index
            if previous_index is not None:
                add_edge_x(index, previous_index)

    current_val = None
    previous_index = None
    current_index = None
    for index in y_sorted_index:
        if positions[index][1] == current_val:
            # 前と同じ
            uf.unite(index, current_index)
        else:
            # 前と違う
            previous_index = current_index
            current_val = positions[index][1]
            current_index = index
            if previous_index is not None:
                add_edge_y(index, previous_index)

    edge_sorted_index = sorted(range(len(edges)), key=lambda i: edges[i][2])
    mst = []
    for ei in edge_sorted_index:
        left = edges[ei][0]
        right = edges[ei][1]
        if not uf.is_same(left, right):
            uf.unite(left, right)
            mst.append(edges[ei])
    ####
    print(sum([v[2] for v in mst]))


if __name__ == '__main__':
    resolve()

