def BF(G, start = 0, INF=10**20):
    d = [INF for i in range(len(G))]
    d[start] = 0
    for i in range(len(G)):
        count = 0
        cycle = set()
        while True:
            count += 1
            update = False
            for j in range(len(G)):
                for k in G[j].keys():
                    if (d[j] != INF) & (d[k] > d[j] + G[j][k]):
                        d[k] = d[j] + G[j][k]
                        update = True
                        if count > len(G):
                          if k in cycle: return d,cycle
                          else: cycle.add(k)

            if not update:
                break

    return d,cycle

