if TYPE_CHECKING:=None:
    from typing import Iterable, Iterator, Tuple, TypeVar
    T = TypeVar('T')
def twin_iterator(iterable: Iterable[T]) -> Iterator[Tuple[T, T]]:
    it = iter(iterable); a = next(it)
    return ((a, (a:=b)) for b in it)


class UnionFind:
    __slots__ = ('table', 'n')

    def __init__(self, n: int):
        self.table = [-1] * n
        self.n = n

    def root(self, x: int):
        stack = []
        table = self.table
        while table[x] >= 0:
            stack.append(x)
            x = table[x]
        for y in stack:
            table[y] = x
        return x

    def find(self, x: int, y: int):
        return self.root(x) == self.root(y)

    def unite(self, x: int, y: int):
        r1 = self.root(x)
        r2 = self.root(y)
        if r1 == r2:
            return

        table = self.table
        d1 = table[r1]
        d2 = table[r2]
        if d1 <= d2:
            table[r2] = r1
            table[r1] += d2
        else:
            table[r1] = r2
            table[r2] += d1

    def sizeof(self, x: int):
        return -self.table[self.root(x)]

    def groups(self):
        root = self.root
        append_to = list.append
        groups: list[list[int]] = [[] for _ in self.table]
        for i in range(self.n):
            append_to(groups[root(i)], i)
        return filter(None, groups)


