from typing import Iterator

def built():
    from operator import itemgetter
    take_first = itemgetter(0)

    n = read_as(int)
    xy_ = read_as(Iterator[int], ..., lines=n)

    xs = [(~0, ~0)]*n; ys = [(~0, ~0)]*n
    for i, (x, y) in enumerate(xy_):
        xs[i] = (x, i)
        ys[i] = (y, i)

    edges: list[tuple[int, int, int]] = []
    push = edges.append

    xs.sort(key=take_first)
    for (xi, i), (xj, j) in twin_iterator(xs):
        push((xj - xi, i, j))

    ys.sort(key=take_first)
    for (yi, i), (yj, j) in twin_iterator(ys):
        push((yj - yi, i, j))

    edges.sort(key=take_first)
    uf = UnionFind(n)
    res = 0
    for d, a, b in edges:
        if uf.find(a, b): continue
        uf.unite(a, b)
        res += d

    return res

