def c_factors_of_factorial(N):
    def exponential_list(n):
        # ret[k]: n!を素因数分解したときのkの指数
        ret = {}
        for j in range(2, n + 1):
            current = j
            ret[j] = 0
            for k in range(2, j + 1):
                while current % k == 0:
                    ret[k] += 1
                    current //= k
            if ret[j] == 0:
                ret.pop(j)
        return ret

    exp_list = exponential_list(N)
    ans = 1
    for e in exp_list.values():
        ans *= e + 1
        ans %= 10**9 + 7
    return ans

