def so_bunkai(num, dicts):
    N = num
    num = int(num**(1 / 2) // 1)
    for i in range(2, num + 2):
        while N % i == 0:
            N /= i
            if i in dicts:
                dicts[i] += 1
            else:
                dicts[i] = 1
    if N != 1:
        if N in dicts:
            dicts[int(N)] += 1
        else:
