def Bellman_Ford(s):
  d[s]=0
  for i in range(N-1):
    update=False
    for ft,c in V.items():
      frm,to=ft
      if d[frm]!=float('inf') and d[to]>d[frm]+c:
        d[to]=d[frm]+c
        update=True
    if not(update):
      break

def Bellma_Ford_rep(n):
  upd=[False for x in range(N)]
  for i in range(N):
    update=False
    for ft,c in V.items():
      frm,to=ft
      if d[to]>d[frm]+c or upd[frm]:
        update=True
        upd[to]=True
    if not(update):
      break
  return upd[n]

