import heapq

def prim_heap(n, edge):
    used = [True] * n #True:不使用
    edgelist = []
    for e in edge[0]:
        heapq.heappush(edgelist,e)
    used[0] = False
    res = 0
    while len(edgelist) != 0:
        minedge = heapq.heappop(edgelist)
        if not used[minedge[1]]:
            continue
        v = minedge[1]
        used[v] = False
        for e in edge[v]:
            if used[e[1]]:
                heapq.heappush(edgelist,e)
        res += minedge[0]
    return res


def solve(N: int, X: "List[int]", Y: "List[int]"):
    XI = sorted((x, i) for i, x in enumerate(X))
    YI = sorted((x, i) for i, x in enumerate(Y))
    edges = [[] for _ in range(N)]
    for (x0, i0), (x1, i1) in zip(XI, XI[1:]):
        d = abs(x0 - x1)
        edges[i0].append((d, i1))
        edges[i1].append((d, i0))
    for (x0, i0), (x1, i1) in zip(YI, YI[1:]):
        d = abs(x0 - x1)
        edges[i0].append((d, i1))
        edges[i1].append((d, i0))
    print(prim_heap(N, edges))
    return


