def func(idx, points, N, lst_s, dp):
    # base case
    if idx == N:
        if points % 10 == 0:
            return 0
        else:
            return points

    # check memo
    if dp.get((idx, points)) is not None:
        return dp[(idx, points)]

    # recursive
    ret = max(
        func(idx = idx + 1, points = points, N = N, lst_s = lst_s, dp = dp), 
        func(idx = idx + 1, points = points + lst_s[idx], N = N, lst_s = lst_s, dp = dp)
        )
    dp[(idx, points)] = ret

    return ret


