class UnionFind:
    def __init__(self, n):
        self._parent = list(range(n))
        self._rank = [0] * n
        self._count = [1] * n
        self._size = n

    def find(self, _id):
        if _id != self._parent[_id]:
            self._parent[_id] = self.find(self._parent[_id])
        return self._parent[_id]

    def unite(self, id1, id2):
        par1, par2 = self.find(id1), self.find(id2)
        if par1 == par2:
            return
        if self._rank[par1] > self._rank[par2]:
            self._parent[par2] = par1
            self._count[par1] += self._count[par2]
        else:
            self._parent[par1] = par2
            if self._rank[par1] == self._rank[par2]:
                self._rank[par2] += 1
            self._count[par2] += self._count[par1]
        self._size -= 1

    def normalize(self):
        for _id in range(len(self._parent)):
            self.find(_id)

    def same(self, id1, id2):
        return self.find(id1) == self.find(id2)

    def size_of_group(self, _id):
        return self._count[self.find(_id)]

    def size(self):
        return self._size


