def solve(N, M):
    d = 10 ** 9 + 7
    N, M = min(N, M), max(N, M)
    if abs(N - M) >= 2:
        return 0
    elif abs(N - M) == 1:
        ans = M
    else:
        ans = 2
    for i in range(1, N + 1):
        ans *= pow(i, 2, d)
        ans %= d
    return ans


