class UnionFind() :
    def __init__(self, N) :
        self.par = [-1] * N

    def root(self, x) :
        while self.par[x] >= 0:
            x = self.par[x]
        return x

    def unite(self, x,y) :
        rx = self.root(x)
        ry = self.root(y)

        if rx != ry :
            if self.par[rx] > self.par[ry] :
                self.par[rx] = ry
            else :
                if self.par[rx] == self.par[ry] :
                    self.par[rx] -= 1
                self.par[ry] = rx

    def same(self, x, y) :
        return self.root(x) == self.root(y)

