import sys
buf = sys.stdin.buffer

class UnionFind:
  def __init__(self, num_of_node):
    self.roots = [-1] * num_of_node
    self.ranks = [1] * num_of_node
    self.groups = num_of_node

  def get_root(self, node):
    root = self.roots[node]
    if root == -1:
      return node
    else:
      root = self.get_root(root)
      self.roots[node] = root
      return root

  def is_same_group(self, node1, node2):
    return self.get_root(node1) == self.get_root(node2)

  def unite(self, node1, node2):
    self.groups -= 1
    root1, root2 = self.get_root(node1), self.get_root(node2)
    rank1, rank2 = self.ranks[root1], self.ranks[root2]
    if rank1 < rank2:
      root1, root2 = root2, root1
    self.roots[root2] = root1
    self.ranks[root2] += self.ranks[root1]

def main():
  n = int(buf.readline())
  XY = map(int, buf.read().split())
  Xs = []
  Ys = []
  for i, (x, y) in enumerate(zip(XY, XY)):
    Xs.append((x-1, i))
    Ys.append((y-1, i))

  Xs.sort()
  Ys.sort()

  edges = []
  for i, ((x, node), (nx, new_node)) in enumerate(zip(Xs[:-1], Xs[1:])):
    edges.append((nx-x, node, new_node))

  for i, ((y, node), (ny, new_node)) in enumerate(zip(Ys[:-1], Ys[1:])):
    edges.append((ny-y, node, new_node))

  edges.sort(reverse=True)

  ans = 0
  uf = UnionFind(n)
  while uf.groups != 1:
    d, node1, node2 = edges.pop()
    if uf.is_same_group(node1, node2):
      continue
    uf.unite(node1, node2)
    ans += d
  print(ans)

if __name__ == "__main__":
    main()

