class UnionFind:
  def __init__(self, n):
    self.n = n
    self.p = [-1]*n
  def leader(self, a):
    while self.p[a]>=0:
      a = self.p[a]
    return a
  def merge(self, a, b):
    x = self.leader(a)
    y = self.leader(b)
    if x==y:
      return x
    if self.p[x]>self.p[y]:
      x, y = y, x
    self.p[x] += self.p[y]
    self.p[y] = x
    return x
  def same(self, a, b):
    return self.leader(a)==self.leader(b)

