      infants = [[] for _ in range(m)]
      highest_rate = [None] * m
      where = [None] * n
      rate = [None] * n

      def entry(i, k):
        where[i] = k
        while infants[k]:
          r, j = heappop(infants[k])
          if where[j] != k or j == i: continue 
          if rate[i] >= -r:
            highest_rate[k] = rate[i]
